(()=>{const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function mount(){if(document.querySelector('#wb-openalex'))return;if(!location.hash.match(/^#research\/[^/]+\/library$/))return;const host=document.querySelector('.wb-tools');if(!host)return;const section=document.createElement('section');section.id='wb-openalex';section.className='wb-tools';section.innerHTML='<p class="eyebrow">DISCOVER WITH PROVENANCE</p><h3>Search scholarly works</h3><form class="research-form"><label>Search query<input name="query" required maxlength="200" placeholder="student wellbeing, climate adaptation…"></label><button class="button primary">Search OpenAlex</button></form><div class="wb-openalex-results" aria-live="polite"></div><p class="wb-hint">Search terms are sent to OpenAlex. Review metadata before saving. REI does not verify relevance or quality automatically.</p>';host.before(section);const form=section.querySelector('form'),results=section.querySelector('.wb-openalex-results');form.onsubmit=async e=>{e.preventDefault();const q=new FormData(form).get('query').trim();if(!q)return;const searchButton=form.querySelector('button');if(searchButton.disabled)return;searchButton.disabled=true;results.innerHTML='<p class="wb-hint">Searching…</p>';try{const r=await fetch('https://api.openalex.org/works?search='+encodeURIComponent(q)+'&per-page=8',{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error(r.status===429?'Too many requests. Wait a moment before retrying.':'OpenAlex is unavailable.');const data=await r.json();results.innerHTML=(data.results||[]).map(x=>{const authors=(x.authorships||[]).slice(0,3).map(a=>a.author?.display_name).filter(Boolean).join('; '),doi=(x.doi||'').replace(/^https?:\/\/doi.org\//,'');const item=encodeURIComponent(JSON.stringify({title:x.title||'',authors,year:String(x.publication_year||''),doi,url:x.primary_location?.landing_page_url||'',venue:x.primary_location?.source?.display_name||''}));return '<article class="wb-record"><h4>'+esc(x.title||'Untitled')+'</h4><p>'+esc([authors,x.publication_year,doi].filter(Boolean).join(' · '))+'</p><button class="button secondary" data-save="'+item+'">Save to this library</button></article>'}).join('')||'<p class="wb-hint">No results found.</p>'}catch{results.innerHTML='<p class="wb-hint">Search unavailable, timed out, or rate limited. Retry shortly; local imports still work.</p>'}finally{searchButton.disabled=false}};results.onclick=async e=>{const b=e.target.closest('[data-save]');if(!b||b.disabled)return;const p=window.REIWorkbench.getProject(),paper=JSON.parse(decodeURIComponent(b.dataset.save));if(p.papers.some(x=>(paper.doi&&x.doi===paper.doi)||x.title.toLowerCase()===paper.title.toLowerCase())){b.textContent='Already saved';return}if(p.papers.length>=200){b.textContent='200-source limit reached';return}b.disabled=true;const record={id:crypto.randomUUID(),...paper,abstract:'',collection:'OpenAlex search',status:'To read',notes:''};p.papers.push(record);try{await window.REIWorkbench.saveProject(p);b.textContent='Saved on this device'}catch{const index=p.papers.indexOf(record);if(index>=0)p.papers.splice(index,1);b.textContent='Could not save · retry';b.disabled=false}}}addEventListener('rrh:route',mount);addEventListener('rei:research-render',mount);mount()})()